import{_ as a,o as i,c as l,a2 as e}from"./chunks/framework.DbKnw1Aw.js";const c=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1794389918000}'),t={name:"guide/quick-start.md"};function n(r,s,o,p,h,d){return i(),l("div",null,[...s[0]||(s[0]=[e(`<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>Sublink Worker 运行在 Cloudflare Workers 上，只依赖一个 KV 命名空间（用于存储短链）。下面几种方式任选其一。</p><h2 id="一键部署" tabindex="-1">一键部署 <a class="header-anchor" href="#一键部署" aria-label="Permalink to &quot;一键部署&quot;">​</a></h2><p><a href="https://deploy.workers.cloudflare.com/?url=https://github.com/chansanya/sublink-worker" target="_blank" rel="noreferrer"><img src="https://deploy.workers.cloudflare.com/button" alt="Deploy to Cloudflare"></a></p><ol><li>点击上面的按钮，Cloudflare 会把仓库复制到你的 GitHub / GitLab 账号。</li><li>在配置页确认仓库名、Worker 名称和 KV 名称，Cloudflare 会自动创建 KV 命名空间并完成绑定。</li><li>部署完成后打开 Worker 的地址即可使用。之后向你的仓库推送代码，会自动重新部署。</li></ol><div class="tip custom-block"><p class="custom-block-title">国内访问</p><p><code>*.workers.dev</code> 域名在部分网络下无法访问。可以在 Cloudflare 控制台为 Worker 绑定自己的域名。</p></div><h2 id="在-cloudflare-控制台连接仓库部署" tabindex="-1">在 Cloudflare 控制台连接仓库部署 <a class="header-anchor" href="#在-cloudflare-控制台连接仓库部署" aria-label="Permalink to &quot;在 Cloudflare 控制台连接仓库部署&quot;">​</a></h2><p>已经有仓库（自己的 fork 或复制的副本）时，可以直接让 Cloudflare 从 GitHub / GitLab 拉代码构建：</p><ol><li>打开 Cloudflare 控制台，进入 <strong>Workers &amp; Pages</strong>，选择创建应用并导入 Git 仓库。</li><li>选择仓库和分支，构建命令留空，部署命令使用默认的 <code>npx wrangler deploy</code>（等同于 <code>npm run deploy</code>）。</li><li>保存并部署。<code>wrangler.jsonc</code> 里的 KV 绑定没有写 <code>id</code>，会在首次部署时自动创建 <code>SUBLINK_KV</code> 并完成绑定。</li><li>之后向该分支推送代码，会自动重新构建并部署。</li></ol><div class="tip custom-block"><p class="custom-block-title">Worker 名称</p><p>控制台里的 Worker 名称最好与 <code>wrangler.jsonc</code> 的 <code>name</code>（<code>sublink-worker</code>）保持一致。名称不一致时，自动创建的 KV 命名空间会按控制台里的 Worker 名称命名，改名后可能多出一个新的命名空间，原有短链不会迁移。</p></div><h2 id="使用-wrangler-手动部署" tabindex="-1">使用 Wrangler 手动部署 <a class="header-anchor" href="#使用-wrangler-手动部署" aria-label="Permalink to &quot;使用 Wrangler 手动部署&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/chansanya/sublink-worker.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sublink-worker</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wrangler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 首次部署会自动创建并绑定 SUBLINK_KV</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">KV 自动创建</p><p><code>wrangler.jsonc</code> 里的 KV 绑定没有写 <code>id</code>，由 wrangler（需 4.45 及以上）在部署时自动创建。想复用已有的 namespace，把它的 <code>id</code> 填到绑定里即可：</p><div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;binding&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;SUBLINK_KV&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;你的 namespace id&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div></div><h2 id="本地运行" tabindex="-1">本地运行 <a class="header-anchor" href="#本地运行" aria-label="Permalink to &quot;本地运行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>打开 <code>http://localhost:8787</code>。本地使用模拟的 KV，数据保存在 <code>.wrangler/state</code>，不需要 Cloudflare 账号，短链的生成与跳转也能完整测试。</p><h2 id="生成第一份订阅" tabindex="-1">生成第一份订阅 <a class="header-anchor" href="#生成第一份订阅" aria-label="Permalink to &quot;生成第一份订阅&quot;">​</a></h2><ol><li><strong>输入源</strong>：粘贴节点链接或机场订阅地址，每行一条，可以混合填写。下方会统计每种协议的数量，无法识别的行会标黄。</li><li><strong>高级选项</strong>（可选）： <ul><li>选择规则预设（精简 / 均衡 / 全面），或点选分类卡片、拖动调整顺序，详见<a href="./rules">规则分类</a>。</li><li>需要对特定域名或 IP 直连、拒绝时，添加<a href="./custom-rules">自定义规则</a>。</li></ul></li><li>点击 <strong>生成订阅</strong>，下方出现 Clash、sing-box、Xray 三条订阅链接，之后的修改会实时反映到链接上。</li><li>想让多台设备使用同一个固定地址，填一个短链路径并生成短链，详见<a href="./links">订阅链接与短链</a>。</li></ol><p>点击顶栏的预览按钮，可以在右侧抽屉里查看实际生成的配置文件。</p>`,19)])])}const u=a(t,[["render",n]]);export{c as __pageData,u as default};
